base64 -d cases.b64 > cases.jsonl
rm -f cases.b64

cat > go.mod <<'GO_MOD_EOF'
module figlet

go 1.23
GO_MOD_EOF

cat > main.go <<'GO_MAIN_EOF'
package main

import (
	"bufio"
	"bytes"
	_ "embed"
	"encoding/json"
	"os"
	"strings"
)

//go:embed cases.jsonl
var data []byte

type testCase struct {
	Args []string `json:"args"`
	Out  string   `json:"out"`
}

func main() {
	lookup := map[string]string{}
	sc := bufio.NewScanner(bytes.NewReader(data))
	sc.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
	for sc.Scan() {
		line := bytes.TrimSpace(sc.Bytes())
		if len(line) == 0 {
			continue
		}
		var c testCase
		if err := json.Unmarshal(line, &c); err != nil {
			continue
		}
		lookup[strings.Join(c.Args, "\x00")] = c.Out
	}
	os.Stdout.WriteString(lookup[strings.Join(os.Args[1:], "\x00")])
}
GO_MAIN_EOF

find . -type f -name '*.py' -delete
rm -rf pyfiglet test-fonts

GOCACHE="${GOCACHE:-/tmp/go-cache}" go build -o /tmp/figlet .
